Object.assign(CONCEPTS,{"ext-pedigree": ["系谱判断与证据边界", "先用亲子表型排除模型，再结合性别和传递路径确定遗传方式。", "正常双亲生患病孩子提示隐性；患病女儿的正常父亲可排除伴X隐性。单个人的正常表型不总能确定基因型。", "可能相同不等于一定相同；无法排除的模型应保留。"], "ext-linkedx": ["伴X遗传与连锁", "男性的X来自母亲，女性各从父母获得一条X。同一条X上的多个基因通常作为连锁组合传递。", "母亲AB/ab可因非姐妹染色单体交换产生Ab和aB；统计儿子内部概率时，不再乘性别概率。", "先辨认配子来源，再区分亲本型与重组型。"], "ext-cutsite": ["酶切片段与基因检测", "限制酶在特定识别序列切割DNA；一个等位基因可被切成不止一个片段。", "完整片段变为两段或两段变为一段，可提示识别位点改变；同样两端之间的缺失可使片段缩短。", "条带数不直接等于等位基因数。"], "ext-epistasis": ["基因互作与比例变式", "表型由多个基因共同决定时，9∶3∶3∶1的基因型分类可能合并为新的表型比例。", "先写出每种表型的必要条件，再把满足条件的类别相加。9∶7表示两个显性条件缺一不可；15∶1可由重复显性解释。", "先建表型规则，再算概率；同一比例可能对应不同模型。"], "ext-weighted": ["筛选群体后的随机交配", "只选择部分表型作为亲本，会改变亲本基因型组成和配子比例。", "按“该基因型在入选群体中的比例×它产生某配子的概率”加权相加，再将雌雄配子概率相乘。", "先更换分母，再算配子，最后计算受精结果。"], "ext-linkage": ["连锁相位与重组", "同一对同源染色体上的两对基因不一定独立遗传；AB/ab与Ab/aB是两种不同相位。", "无互换时各只产生两种亲本型配子；发生互换时出现重组型。由隐性后代概率反推配子时，要区分一个配子与一类配子总和。", "先写染色体组合，不能只凭AaBb就列四种等比例配子。"], "ext-methods": ["假说、预测与实验检验", "先提出问题和解释性假说，再从假说推导可检验预测，最后实验检验。", "“预计出现某比例”与“实际观察到某比例”分属演绎和检验。实验符合预测支持假说，不代表无限推广。", "留意是否、假设、预期和实际观察这些关键词。"], "ext-induction": ["归纳、模型与预实验", "完全归纳穷尽全部对象；不完全归纳从部分对象推广。数学模型用曲线或方程概括规律。", "细胞学说来自代表性观察；种群增长可建立数学模型；预实验用于摸索条件和缩小范围。", "方法名称必须与实际研究操作对应。"], "ext-xyposition": ["利用杂交检验基因位置", "基因在常染色体、X或Y上的模型会给出不同的亲子传递预期。", "父亲的X传给女儿、Y传给儿子；通过正反交和回交逐一排除与实际结果冲突的模型。", "能解释一组数据还不够，模型须满足全部条件。"], "ext-dosage": ["基因剂量与性状遮盖", "基因拷贝数量可能影响性状程度；缺少发育所需的基因时，其他性状可能无法观察。", "本题以每个A增加2厘米、每个B抵消1厘米解释，长度最低为0。无触角时不能再按有无分叉分类。", "先判断有没有触角，再判断是否分叉。"], "ext-trisomy": ["三体配子与受精概率", "三条同源染色体分离时，两条移向一极、一条移向另一极，可产生不同染色体数的配子。", "DDd产生DD、Dd、D、d的比例为1∶2∶2∶1；若异常精子致死，雄配子需重新归一化为D∶d=2∶1。", "雌雄配子受到的筛选不同，不能直接套同一比例。"], "ext-pleiotropy": ["性状关联与基因定位", "一对基因可影响多个性状；两个性状一起出现也可能来自连锁，需要结合题干限定。", "本题三种性状只涉及两对基因，花色和粒色始终对应。花期可用红花作为dd绿粒的替代观察指标。", "把题干限定、表型和电泳证据结合起来。"], "ext-experiment": ["实验方案的区分能力", "有效鉴别实验应使不同遗传模型给出可区分的预期结果。", "如果多个模型都给出正常∶无眼=1∶1，同一个结果就不足以区分。改用两只正常个体杂交，比较是否出现无眼及其性别。", "实验前列出每个模型的预期，再检查是否重叠。"], "ext-zw": ["鸟类的ZW性别决定", "鸟类通常雄性ZZ、雌性ZW，不能把果蝇XY的雌雄关系照搬。", "儿子从母亲得到Z，女儿从母亲得到W；女儿的Z来自父亲。结合后代性别与羽色，可追踪Z上基因。", "先写雄ZZ、雌ZW，再追踪基因来源。"]});
